// VM acme = établissement UNIQUE Rungis (94065). Règle ETT : rattachement RUP.
// Robuste : accepte l'enveloppe Opendatasoft ({results:[...]}) OU des items déjà splittés.
const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j.results)) rows.push(...j.results);  // enveloppe API
  else rows.push(j);                                       // déjà splitté
}

const out = [];
for (const r of rows) {
  if (r.code_commune !== '94065') continue;     // Rungis seulement
  if (r.date_fin) continue;                      // ligne EN COURS (date_fin null)
  const taux = Number(r.taux_vm);                // pourcentage (3.2)
  if (!Number.isFinite(taux)) continue;
  const fraction = taux / 100;                   // engine attend une FRACTION (0.032)
  const d = String(r.date_debut || '');          // "20240201"
  const dateEffet = /^\d{8}$/.test(d) ? `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}` : null;

  out.push({ json: {
    sourceKey: 'urssaf_vm',
    paramKey: 'vm.94065',
    tauxJsonPath: 'versement_mobilite.taux_standard',
    valeurProposee: String(fraction),            // "0.032"
    dateEffet,                                    // "2024-02-01"
    urlSource: 'https://open.urssaf.fr/api/explore/v2.1/catalog/datasets/table_taux_vmrr/records?where=code_commune%3D%2294065%22',
    extrait: `RUNGIS (94065) — VM ${taux}% (${fraction}) effet ${dateEffet}`,
    confiance: 1.0,
  }});
}
return out;

const root = $input.first().json;

// descendre jusqu'à la série, puis aux observations
const ds = root['message:StructureSpecificData']?.['message:DataSet'] ?? root['message:DataSet'];
let series = ds['Series'];
series = Array.isArray(series) ? series[0] : series;   // 1 seule série ici
let obs = series['Obs'];
obs = Array.isArray(obs) ? obs : [obs];                // lastNObservations=1 → objet unique

// lit un attribut qu'il soit à plat OU sous "$" (selon config du nœud XML)
const attr = (o, k) => o?.[k] ?? o?.['$']?.[k];

// garder la plus récente par période
const last = obs.slice().sort((a, b) =>
  String(attr(b, 'TIME_PERIOD')).localeCompare(String(attr(a, 'TIME_PERIOD'))))[0];

const valeur  = attr(last, 'OBS_VALUE');     // "12.31"
const periode = attr(last, 'TIME_PERIOD');   // "2026-06"

return [{ json: {
  sourceKey: 'insee_smic',
  paramKey: 'smic.horaire',
  tauxJsonPath: 'smic.horaire_brut',
  valeurProposee: String(valeur).replace(',', '.'),
  dateEffet: periode ? `${periode}-01` : null,   // "2026-06" → "2026-06-01"
  urlSource: 'https://api.insee.fr/series/BDM/V1/data/SERIES_BDM/000822484',
  extrait: `SMIC horaire INSEE ${valeur} € (période ${periode})`,
  confiance: 1.0,
}}];

// S11 v2 (2026-07-22) — parse la GRILLE taux neutre métropole + l'ABATTEMENT
// contrats courts depuis la page BOFiP BOI-BAREME-000037, et émet 2 signaux
// veille MAPPÉS (plus informatifs) : pas.bareme_metropole (grille JSON) +
// pas.abattement_interim (nombre). Le taux PERSO PAS vient de la DSN (CRM 94) ;
// la grille neutre et l'abattement, eux, n'ont AUCUN flux DGFiP → cette veille.
const html = String($input.first().json.data || $input.first().json.body || '');
const out = [];
const clean = (s) => s.replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/ | /g, ' ').replace(/\s+/g, ' ').trim();

// Version en vigueur (identifiant BOI le plus récent présent sur la page).
const dates = [...html.matchAll(/BOI-BAREME-000037-(\d{8})/g)].map((m) => m[1]).sort();
const ver = dates.length ? `BOI-BAREME-000037-${dates[dates.length - 1]}` : 'BOI-BAREME-000037';
const urlSource = 'https://bofip.impots.gouv.fr/bofip/11255-PGP.html';

// ── 1. Grille MÉTROPOLE : 1re <table> dont le caption contient "métropole" ──
const tables = html.match(/<table[\s\S]*?<\/table>/gi) || [];
const metro = tables.find((t) => /m[ée]tropole/i.test((t.match(/<caption[^>]*>([\s\S]*?)<\/caption>/i) || [])[1] || ''));
let grille = null;
if (metro) {
  const rows = [];
  for (const tr of metro.match(/<tr[\s\S]*?<\/tr>/gi) || []) {
    const tds = [...tr.matchAll(/<td[\s\S]*?<\/td>/gi)].map((m) => m[0]);
    if (tds.length < 2) continue; // ligne d'en-tête (th) ignorée
    const libelle = clean(tds[0]);
    const taux = Number(clean(tds[1]).replace(/[^\d,\.]/g, '').replace(',', '.'));
    if (!Number.isFinite(taux)) continue;
    // Borne SUP exclue : "inférieure à X" (1re) ou "...et inférieure à X" ; dernière tranche = pas de borne → 9999999.
    const inf = libelle.match(/inf[ée]rieure à ([\d ]+)/i);
    const borne = inf ? Number(inf[1].replace(/\s/g, '')) : 9999999;
    rows.push([borne, taux]);
  }
  // Garde-fous anti-parsing cassé : 20 tranches, 1re borne plausible (SMIC~), dernière = 9999999/43.
  const ok = rows.length === 20 && rows[0][0] >= 1500 && rows[0][0] <= 1800 && rows[0][1] === 0 && rows[rows.length - 1][0] === 9999999 && rows[rows.length - 1][1] === 43;
  if (ok) grille = rows;
}
if (grille) {
  out.push({ json: {
    sourceKey: 'bofip_pas_bareme',
    paramKey: 'pas.bareme_metropole',
    tauxJsonPath: 'pas.bareme_metropole',
    valeurProposee: JSON.stringify(grille),
    dateEffet: '2026-05-01',
    urlSource,
    extrait: `Grille taux neutre métropole (${grille.length} tranches) — ${ver}`,
    confiance: 1.0,
  } });
}

// ── 2. Abattement contrats courts (CGI 204 H III bis, indexé SMIC) ──────────
const txt = html.replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/ | /g, ' ');
const abM = txt.match(/abattement applicable aux contrats courts[^.]*?[ée]gal à\s*([\d ]+)\s*euros/i);
if (abM) {
  const abatt = Number(abM[1].replace(/\s/g, ''));
  const dEffetJuin = /1\s*er\s+juin\s+2026/i.test(txt);
  if (Number.isFinite(abatt) && abatt >= 500 && abatt <= 2000) {
    out.push({ json: {
      sourceKey: 'bofip_pas_bareme',
      paramKey: 'pas.abattement_interim',
      tauxJsonPath: 'pas.abattement_interim_mensuel',
      valeurProposee: String(abatt),
      dateEffet: dEffetJuin ? '2026-06-01' : null,
      urlSource,
      extrait: `Abattement contrats courts (CGI 204 H III bis) = ${abatt} € — ${ver}`,
      confiance: 1.0,
    } });
  }
}

// Fallback : si le parsing échoue TOTALEMENT (page BOFiP restructurée), on émet
// le signal informatif legacy (version) pour ne pas perdre l'alerte de changement.
if (out.length === 0 && dates.length) {
  out.push({ json: {
    sourceKey: 'bofip_pas_bareme',
    paramKey: 'pas.bareme_taux_neutre',
    tauxJsonPath: '',
    valeurProposee: ver,
    dateEffet: `${dates[dates.length - 1].slice(0, 4)}-${dates[dates.length - 1].slice(4, 6)}-${dates[dates.length - 1].slice(6, 8)}`,
    urlSource,
    extrait: `⚠️ Parsing grille/abattement KO (structure BOFiP ?) — version en vigueur ${ver} à vérifier manuellement`,
    confiance: 0.5,
  } });
}

return out;

// Liste PA (plateformes agreees e-invoicing) -> signal INFORMATIF.
// Fingerprint des noms commerciaux (1re colonne) tries -> la webapp deduplique :
// notif seulement quand la liste change (ajout / retrait / renommage).
const noms = [];
for (const item of $input.all()) {
  const v = Object.values(item.json);
  const nom = String(v[0] ?? '').trim();
  if (nom && nom.toLowerCase() !== 'nom commercial') noms.push(nom);
}
noms.sort((a, b) => a.localeCompare(b));
let h = 5381;
const s = noms.join('|');
for (let i = 0; i < s.length; i++) h = (((h << 5) + h) ^ s.charCodeAt(i)) >>> 0;
return [{ json: {
  sourceKey: 'impots_pdp',
  paramKey: 'pdp.liste_audit',
  tauxJsonPath: '',
  valeurProposee: `${noms.length} plateformes (fp ${h})`,
  dateEffet: null,
  urlSource: 'https://www.impots.gouv.fr/je-consulte-la-liste-des-plateformes-agreees',
  extrait: `PA en attente de rapport d'audit : ${noms.length} plateformes - ${noms.slice(0, 8).join(', ')}${noms.length > 8 ? '...' : ''}`,
  confiance: 1.0,
}}];

const html = String($input.first().json.data || $input.first().json.body || '');
const m = html.match(/Version\s+(\d{4}\.\d+\.\d+\.\d+)/i);
if (!m) return [];
const ver = m[1];
const dm = html.match(new RegExp(ver.replace(/\./g, '\\.') + '[^0-9]{0,40}(\\d{1,2}\\s+[a-zA-Zéû]+\\s+\\d{4})'));
return [{ json: {
  sourceKey: 'dsn_val',
  paramKey: 'dsn.val_version',
  tauxJsonPath: '',
  valeurProposee: ver,
  dateEffet: null,
  urlSource: 'https://www.net-entreprises.fr/declaration/outils-de-controle-dsn-val/',
  extrait: `DSN-VAL version ${ver}` + (dm ? ` du ${dm[1]}` : ''),
  confiance: 1.0,
}}];

// BOSS Table des parametres -> signaux veille (valeurs structurees).
// Lecture par POSITION (header Latin-1) : 0=Code 1=Libelle 2=Valeur 3=DateEffet 4=DateFin.
// Match par CODE (ASCII stable). Gere espaces milliers (4 005) + virgule (38,21).
// Regle : ne garder que la ligne EN COURS (date de fin vide ou //).
// Exception RGDU ref SMIC : GELE au 1er janvier (decret 2026-509) -> ligne 01/01.
const MAP = {
  // SMIC courant : PAS depuis BOSS (table datee = en retard des revalos en
  // cours d'annee, ex juin) -> via INSEE BDM (S3, temps reel). BOSS ne sert
  // ici que les parametres ANNUELS/GELES (fiables) + le SMIC ref RGDU (gele).
  PSS_M_METROP: { paramKey: 'plafonds.pmss', tauxJsonPath: 'plafonds.pmss_2026', scale: 1 },
  PSS_A_METROP: { paramKey: 'plafonds.pass', tauxJsonPath: 'plafonds.pass_annuel', scale: 1 },
  COT_RGDU_Tmin_METROP: { paramKey: 'rgdu.tmin', tauxJsonPath: 'rgdu.t_min', scale: 0.01 },
  COT_RGDU_Tdelta_49_METROP: { paramKey: 'rgdu.tdelta_moins', tauxJsonPath: 'rgdu.t_delta_50_moins', scale: 0.01 },
  COT_RGDU_Tdelta_50_METROP: { paramKey: 'rgdu.tdelta', tauxJsonPath: 'rgdu.t_delta_50_plus', scale: 0.01 },
  FNO_REST_INT:       { paramKey: 'frais.panier_repas', tauxJsonPath: 'plafonds_urssaf_indemnites.panier_seuil_J', scale: 1 },
  COT_FNAL_50_METROP: { paramKey: 'cotisations.fnal_pat', tauxJsonPath: 'rubriques.3070.tauxPat', scale: 0.01 },
};  


const num = (s) => Number(String(s ?? '').split('').filter((c) => '06 00 00 00 00,.-'.includes(c)).join('').replace(',', '.'));
const toIso = (d) => { const p = String(d || '').trim().split('/'); return (p.length === 3 && p[2].length === 4) ? p[2] + '-' + p[1] + '-' + p[0] : null; };
const isCurrent = (f) => !f || f === '//';
const year = new Date().getFullYear();
const jan1 = '01/01/' + year;
const rows = $input.all().map((it) => Object.values(it.json));
const out = [];
for (const v of rows) {
  const conf = MAP[String(v[0] ?? '').trim()];
  if (!conf) continue;
  if (!isCurrent(String(v[4] ?? '').trim())) continue;
  const brut = num(v[2]);
  if (!Number.isFinite(brut)) continue;
  const valeur = parseFloat((brut * conf.scale).toFixed(6));
  out.push({ json: {
    sourceKey: 'boss_table_parametres',
    paramKey: conf.paramKey,
    tauxJsonPath: conf.tauxJsonPath,
    valeurProposee: String(valeur),
    dateEffet: toIso(v[3]),
    urlSource: 'https://boss.gouv.fr/portail/accueil/table-des-parametres.html',
    extrait: String(v[1] ?? '').trim() + ' = ' + v[2] + ' (BOSS, effet ' + v[3] + ')',
    confiance: 1.0,
  } });
}
// RGDU ref SMIC = SMIC_H_METROP en vigueur au 01/01 (gele toute l'annee).
const ref = rows.find((v) => String(v[0]).trim() === 'SMIC_H_METROP' && String(v[3]).trim() === jan1);
if (ref) {
  const r = num(ref[2]);
  if (Number.isFinite(r)) {
    out.push({ json: {
      sourceKey: 'boss_table_parametres',
      paramKey: 'rgdu.smic',
      tauxJsonPath: 'rgdu.smic_horaire',
      valeurProposee: String(r),
      dateEffet: year + '-01-01',
      urlSource: 'https://boss.gouv.fr/portail/accueil/table-des-parametres.html',
      extrait: 'SMIC de reference RGDU (gele au 01/01) = ' + ref[2],
      confiance: 1.0,
    } });
  }
}
// Taux maladie & allocations familiales (bandeau RGDU) : plein + reduit.
// La reduction partage le meme code BOSS (REDUC_COT_AF_SS_METROP) pour AF et
// maladie -> on desambigue par le LIBELLE (col 1).
const curRow = (code) => rows.find((v) => String(v[0]).trim() === code && isCurrent(String(v[4] ?? '').trim()));
const reducRow = (needle) => rows.find((v) => String(v[0]).trim() === 'REDUC_COT_AF_SS_METROP' && isCurrent(String(v[4] ?? '').trim()) && String(v[1] ?? '').toLowerCase().includes(needle));
const emitRate = (paramKey, tauxJsonPath, pct, dateEffet, label) => {
  if (!Number.isFinite(pct)) return;
  out.push({ json: {
    sourceKey: 'boss_table_parametres',
    paramKey,
    tauxJsonPath,
    valeurProposee: String(parseFloat((pct / 100).toFixed(6))),
    dateEffet,
    urlSource: 'https://boss.gouv.fr/portail/accueil/table-des-parametres.html',
    extrait: label + ' = ' + pct + ' % (BOSS)',
    confiance: 1.0,
  } });
};
const afR = curRow('COT_AF_SS_METROP');
const amR = curRow('COT_AM_SS_METROP');
const afFull = afR ? num(afR[2]) : NaN;
const amFull = amR ? num(amR[2]) : NaN;
const afReducR = reducRow('famil');
const amReducR = reducRow('maladie');
const afReduc = afReducR ? num(afReducR[2]) : NaN;
const amReduc = amReducR ? num(amReducR[2]) : NaN;
const afDate = afR ? toIso(afR[3]) : null;
const amDate = amR ? toIso(amR[3]) : null;
emitRate('cotisations.famille_pat_normal', 'seuils_cotisations.famille_pat_normal', afFull, afDate, 'Allocations familiales (taux plein)');
emitRate('cotisations.maladie_pat_normal', 'seuils_cotisations.maladie_pat_normal', amFull, amDate, 'Maladie patronale (taux plein)');
if (Number.isFinite(afFull) && Number.isFinite(afReduc)) emitRate('cotisations.famille_pat_reduit', 'seuils_cotisations.famille_pat_reduit', afFull - afReduc, afDate, 'Allocations familiales (taux reduit)');
if (Number.isFinite(amFull) && Number.isFinite(amReduc)) emitRate('cotisations.maladie_pat_reduit', 'seuils_cotisations.maladie_pat_reduit', amFull - amReduc, amDate, 'Maladie patronale (taux reduit)');
return out;

// Scrape l'URL du CSV "Table des parametres" depuis la page BOSS.
// Le chemin est date (202601_...) et change a chaque MAJ -> on l'extrait au
// lieu de le coder en dur (plus jamais de 404 sur le chemin date).
const html = String($input.first().json.data || $input.first().json.body || '');
const m = html.match(/href="([^"]*Table des param[^"]*\.csv)"/i);
if (!m) throw new Error('Lien CSV BOSS introuvable sur la page table-des-parametres.');
const raw = m[1].startsWith('http') ? m[1] : 'https://boss.gouv.fr' + m[1];
return [{ json: { csvUrl: encodeURI(raw) } }];

// Parser URSSAF taux — v2 durcie (décode entités + split caption + <tr> tolérant + auto-diagnostic).
function decode(s) {
  return s
    .replace(/&nbsp;/g, ' ').replace(/&#39;|&apos;/g, "'")
    .replace(/&eacute;/g, 'é').replace(/&egrave;/g, 'è').replace(/&ecirc;/g, 'ê').replace(/&euml;/g, 'ë')
    .replace(/&agrave;/g, 'à').replace(/&acirc;/g, 'â')
    .replace(/&ocirc;/g, 'ô').replace(/&ouml;/g, 'ö')
    .replace(/&ugrave;/g, 'ù').replace(/&ucirc;/g, 'û')
    .replace(/&icirc;/g, 'î').replace(/&iuml;/g, 'ï').replace(/&ccedil;/g, 'ç')
    .replace(/&Eacute;/g, 'É').replace(/&Egrave;/g, 'È').replace(/&amp;/g, '&');
}
function parseUrssafTaux(rawHtml) {
  const html = decode(rawHtml);
  const stripTags = (s) => s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const toFrac = (p) => { const n = Number(String(p).replace('%', '').replace(',', '.').trim()); return Number.isFinite(n) ? n / 100 : NaN; };
  const idx = (re) => { const m = html.match(re); return m ? m.index : -1; };
  let iEmp = idx(/patronaux applicables/i); if (iEmp < 0) iEmp = html.indexOf('Taux de cotisations employeur');
  let iSal = idx(/salariaux applicables/i); if (iSal < 0) iSal = html.indexOf('Taux de cotisations salari');
  let empSection, salSection;
  if (iEmp >= 0 && iSal >= 0) {
    if (iEmp < iSal) { empSection = html.slice(iEmp, iSal); salSection = html.slice(iSal); }
    else { salSection = html.slice(iSal, iEmp); empSection = html.slice(iEmp); }
  } else { empSection = iEmp >= 0 ? html.slice(iEmp) : ''; salSection = iSal >= 0 ? html.slice(iSal) : ''; }
  const rowsOf = (section) => {
    const rows = [];
    for (const m of section.matchAll(/<tr\b[^>]*table_custom__tbody[^>]*>([\s\S]*?)<\/tr>/gi)) {
      const tr = m[1];
      const th = tr.match(/<th\b[^>]*>([\s\S]*?)<\/th>/i);
      const td = tr.match(/<td\b[^>]*>([\s\S]*?)<\/td>/i);
      if (th && td) rows.push({ libelle: stripTags(th[1]), valeur: stripTags(td[1]) });
    }
    return rows;
  };
  const emp = rowsOf(empSection), sal = rowsOf(salSection);
  const trTotal = (html.match(/table_custom__tbody/g) || []).length;
  if (emp.length === 0 && sal.length === 0) {
    throw new Error('PARSE VIDE — table_custom__tbody x' + trTotal + ' | iEmp=' + iEmp + ' iSal=' + iSal + ' | len=' + html.length + '. Si x0 -> tables absentes du HTML brut (rendu JS) ; sinon -> markup <tr> different (copie-moi un <tr>).');
  }
  const find = (rows, re, notRe) => rows.find((r) => re.test(r.libelle) && (!notRe || !notRe.test(r.libelle)));
  const cap = (t, re) => (t && t.match(re) ? t.match(re)[1] : null);
  const out = [];
  const push = (paramKey, tauxJsonPath, valStr) => { if (valStr == null) return; const f = toFrac(valStr); if (!Number.isFinite(f) || f <= 0 || f > 0.5) return; out.push({ paramKey, tauxJsonPath, valeurProposee: f.toFixed(5) }); };
  const vieEmp = find(emp, /assurance vieillesse/i);
  if (vieEmp) {
    push('cotisations.vieillesse_deplaf_pat', 'rubriques.3010d.tauxPat', cap(vieEmp.valeur, /([\d.,]+)\s*%\s*sur la totalit/i));
    push('cotisations.vieillesse_plaf_pat', 'rubriques.3010.tauxPat', cap(vieEmp.valeur, /et\s*([\d.,]+)\s*%\s*dans la limite/i));
  }
  const chom = find(emp, /assurance ch[oô]mage/i);
  if (chom) push('cotisations.chomage_pat', 'rubriques.3100.tauxPat', cap(chom.valeur, /([\d.,]+)\s*%/));
  const appr = find(emp, /taxe d'apprentissage/i, /haut-rhin|moselle|bas-rhin|formation profession/i);
  if (appr) {
    push('cotisations.apprentissage_principale', 'rubriques.3930.tauxPat', cap(appr.valeur, /principale[^%\d]*([\d.,]+)\s*%/i));
    push('cotisations.apprentissage_solde', 'rubriques.3931.tauxPat', cap(appr.valeur, /solde[^%\d]*([\d.,]+)\s*%/i));
  }
  const form = find(emp, /contribution formation profession/i);
  if (form) push('cotisations.formation_legale', 'rubriques.3920.tauxPat', cap(form.valeur, /11\s*salari[eé]s et plus[\s:]*([\d.,]+)\s*%/i));
  const vieSal = find(sal, /assurance vieillesse/i);
  if (vieSal) {
    push('cotisations.vieillesse_deplaf_sal', 'rubriques.3010d.tauxSal', cap(vieSal.valeur, /([\d.,]+)\s*%\s*sur la totalit/i));
    push('cotisations.vieillesse_plaf_sal', 'rubriques.3010.tauxSal', cap(vieSal.valeur, /et\s*([\d.,]+)\s*%\s*dans la limite/i));
  }
  const csgImp = find(sal, /csg imposable/i);
  if (csgImp) push('cotisations.csg_non_deductible', 'rubriques.5100.tauxSal', cap(csgImp.valeur, /([\d.,]+)\s*%/));
  const csgNon = find(sal, /csg non imposable/i);
  if (csgNon) push('cotisations.csg_deductible', 'rubriques.4100.tauxSal', cap(csgNon.valeur, /([\d.,]+)\s*%/));
  const crds = find(sal, /crds/i);
  if (crds) push('cotisations.crds', 'rubriques.5101.tauxSal', cap(crds.valeur, /([\d.,]+)\s*%/));
  return out;
}
const html = String($input.first().json.data ?? $input.first().json.body ?? '');
return parseUrssafTaux(html).map((r) => ({ json: {
  sourceKey: 'urssaf_taux_secteur_prive', paramKey: r.paramKey, tauxJsonPath: r.tauxJsonPath,
  valeurProposee: r.valeurProposee, dateEffet: '2026-01-01',
  urlSource: 'https://www.urssaf.fr/accueil/outils-documentation/taux-baremes/taux-cotisations-secteur-prive.html',
  extrait: r.paramKey + ' = ' + r.valeurProposee + ' (fraction, source URSSAF)', confiance: 0.9,
} }));
